  fid_assume_1: { en: "RSSI ≠ distance: radar rings are strength bands, never physical meters.", es: "RSSI ≠ distancia: los anillos del radar son bandas de fuerza señal, nunca metros físicos." },
  fid_assume_2: { en: "Angle ≠ orientation: device angle is derived from the MAC address hash; BLE provides no orientation.", es: "Ángulo ≠ orientación: el ángulo de dispositivo se deriva del hash de la dirección MAC; BLE no proporciona orientación." },
  fid_assume_3: { en: "No hardware: models do not access Bluetooth, Wi-Fi or /proc adapters. Inputs are synthetic or sampled.", es: "Sin hardware: los modelos no acceden a adaptadores Bluetooth, Wi-Fi ni /proc. Las entradas son sintéticas o de muestra." },
  fid_assume_4: { en: "No original I/O: iw, nmcli, bleak and curses are not invoked. I/O boundaries replaced by deterministic inputs.", es: "Sin I/O original: no se invocan iw, nmcli, bleak ni curses. Límites de E/S sustituidos por entradas deterministas." },
  fid_assume_5: { en: "Configurable clock: wall time replaced by a configurable epoch clock for reproducibility.", es: "Reloj configurable: el tiempo de pared se sustituye por un reloj de época configurable para reproducibilidad." },
  fid_assume_6: { en: "GenArt upstream tests: the original engine has 5 failing tests (not reproduced here).", es: "GenArt tests upstream: el motor original tiene 5 tests fallidos (no reproducidos aquí)." },
  fid_limit_1: { en: "Radio hardware: WTM and BLE require real Wi-Fi/BLE adapters for live scanning; replaced with synthetic data.", es: "Hardware de radio: WTM y BLE requieren adaptadores Wi-Fi/BLE reales para escaneo en vivo; sustituidos por datos sintéticos." },
  fid_limit_2: { en: "SQLite database: persistence replaced by in-memory store with the same query semantics.", es: "Base de datos SQLite: la persistencia se sustituyó por almacén en memoria con la misma semántica de consultas." },
  fid_limit_3: { en: "Terminal interface: curses/screen replaced by HTML canvas and radar cell geometry.", es: "Interfaz de terminal: curses/pantalla sustituidos por lienzo HTML y geometría de celdas radar." },
  fid_limit_4: { en: "Linux /proc: PEM uses synthetic snapshots; it does not read /proc from the host system.", es: "/proc de Linux: el modelo PEM usa instantáneas sintéticas; no lee /proc del sistema anfitrión." },
  fid_limit_5: { en: "File export: GIF/PNG/ANSI for GenArt is not at model level; pixel arrays are exported as data.", es: "Exportación de archivo: GIF/PNG/ANS del GenArt no están en el nivel de modelo; los arrays de píxeles se exportan como datos." },
  fid_limit_6: { en: "No unproven capabilities: nothing is claimed that is not implemented and tested.", es: "No se afirman capacidades: nada se afirma que no esté implementado y probado." },
