  box_descend: { en: "DESCEND: QUIET node with space spawns a child with its tag and jittered payload. (tag=3, w=0.9)", es: "DESCEND: nodo QUIET con espacio genera hijo con su etiqueta y payload con jitter. (tag=3, w=0.9)" },
